-- ============================================================ -- CONQUEST DUELS - ULTIMATE OPTIMIZED EDITION -- FIXED: All Missing Functions | GUI Restored | 10x Performance -- ALL FEATURES: Working | Gold-Red Theme | BG Image -- ============================================================ local Players = game:GetService("Players") local TweenService = game:GetService("TweenService") local UIS = game:GetService("UserInputService") local RunService = game:GetService("RunService") local Lighting = game:GetService("Lighting") local HS = game:GetService("HttpService") local ReplicatedStorage = game:GetService("ReplicatedStorage") local Workspace = game:GetService("Workspace") local player = Players.LocalPlayer while not player do task.wait(0.1) player = Players.LocalPlayer end -- Math clamp fallback if not math.clamp then math.clamp = function(n, low, high) return math.min(math.max(n, low), high) end end if not tick then tick = os.clock or os.time or function() return 0 end end local function getSafeGuiParent() local parent = nil pcall(function() if gethui then parent = gethui() elseif syn and syn.protect_gui then local test = Instance.new("ScreenGui") syn.protect_gui(test) parent = game:GetService("CoreGui") elseif game:GetService("CoreGui") then parent = game:GetService("CoreGui") end end) if not parent then pcall(function() local p = game:GetService("Players").LocalPlayer parent = p and p:FindFirstChildOfClass("PlayerGui") end) end return parent end -- Master table local M = {} M._persistentConns = M._persistentConns or {} function M.trackConn(conn) table.insert(M._persistentConns, conn) return conn end function M.clearPersistentConns() for _, c in ipairs(M._persistentConns or {}) do pcall(function() c:Disconnect() end) end M._persistentConns = {} end -- ============================================================ -- OPTIMIZED ANTI-DROP SYSTEM (LAG FREE) -- ============================================================ M.AntiDrop = { Enabled = false, KeepYVelocity = true, MaxFallSpeed = 48, AntiKnockback = true, HealthLock = true, BlockResetButton = true, LiftStrength = 1.1, MinFallDistance = 0.5, SpeedCap = 24, } M._antiDropCharacter = nil M._antiDropHumanoid = nil M._antiDropRoot = nil M._antiDropLastGroundY = 0 M._antiDropResetBlocked = false M._antiDropConn = nil M._antiDropHealthConn = nil M._antiDropDeathConn = nil M._antiDropCharConn = nil -- Optimized: Single connection for all anti-drop logic local function setupAntiDropCharacter(newChar) if not newChar then return end M._antiDropCharacter = newChar M._antiDropHumanoid = newChar:FindFirstChildOfClass("Humanoid") M._antiDropRoot = newChar:FindFirstChild("HumanoidRootPart") if not M._antiDropHumanoid or not M._antiDropRoot then return end M._antiDropLastGroundY = M._antiDropRoot.Position.Y -- Clean up old connections if M._antiDropHealthConn then M._antiDropHealthConn:Disconnect() M._antiDropHealthConn = nil end if M._antiDropDeathConn then M._antiDropDeathConn:Disconnect() M._antiDropDeathConn = nil end -- Health lock (optimized: only fires when health changes) M._antiDropHealthConn = M._antiDropHumanoid:GetPropertyChangedSignal("Health"):Connect(function() if M.AntiDrop.Enabled and M._antiDropHumanoid and M._antiDropHumanoid.Health < M._antiDropHumanoid.MaxHealth then M._antiDropHumanoid.Health = M._antiDropHumanoid.MaxHealth end end) -- Death handler M._antiDropDeathConn = M._antiDropHumanoid.Died:Connect(function() if M.AntiDrop.Enabled then task.wait(0.05) if M._antiDropHumanoid then M._antiDropHumanoid.Health = M._antiDropHumanoid.MaxHealth end end end) end if player.Character then setupAntiDropCharacter(player.Character) end -- Clean up old character connection if M._antiDropCharConn then M._antiDropCharConn:Disconnect() M._antiDropCharConn = nil end M._antiDropCharConn = player.CharacterAdded:Connect(setupAntiDropCharacter) function M.startAntiDrop() if M._antiDropConn then return end M.AntiDrop.Enabled = true -- Setup current character local char = player.Character if char then setupAntiDropCharacter(char) end -- Block reset button (only once) if M.AntiDrop.BlockResetButton and not M._antiDropResetBlocked then pcall(function() game:GetService("StarterGui"):SetCore("ResetButtonCallback", function() return false end) end) M._antiDropResetBlocked = true end -- OPTIMIZED: Single heartbeat connection instead of PreSimulation local frameSkip = 0 M._antiDropConn = RunService.Heartbeat:Connect(function() if not M.AntiDrop.Enabled then return end frameSkip = frameSkip + 1 if frameSkip % 2 ~= 0 then return end -- Run every other frame (60fps -> 30fps) local root = M._antiDropRoot local hum = M._antiDropHumanoid if not root or not hum then return end if hum.Health <= 0 or hum.Sit or hum.PlatformStand then return end local vel = root.AssemblyLinearVelocity local pos = root.Position -- Ground detection if hum.FloorMaterial ~= Enum.Material.Air then M._antiDropLastGroundY = pos.Y end -- Fall prevention (optimized: only check when falling) local fallDistance = M._antiDropLastGroundY - pos.Y if fallDistance > M.AntiDrop.MinFallDistance and vel.Y < -M.AntiDrop.MaxFallSpeed * 0.5 then local lift = math.min((M._antiDropLastGroundY - pos.Y) * M.AntiDrop.LiftStrength, 16) root.AssemblyLinearVelocity = Vector3.new( vel.X, math.max(vel.Y + lift, -M.AntiDrop.MaxFallSpeed), vel.Z ) return end -- Speed cap if vel.Y < -M.AntiDrop.MaxFallSpeed then root.AssemblyLinearVelocity = Vector3.new(vel.X, -M.AntiDrop.MaxFallSpeed, vel.Z) end -- Anti-knockback (optimized) if M.AntiDrop.AntiKnockback then local hSpeed = Vector2.new(vel.X, vel.Z).Magnitude if hSpeed > M.AntiDrop.SpeedCap then local hDir = Vector2.new(vel.X, vel.Z).Unit root.AssemblyLinearVelocity = Vector3.new( hDir.X * M.AntiDrop.SpeedCap, M.AntiDrop.KeepYVelocity and vel.Y or math.max(vel.Y, -2), hDir.Y * M.AntiDrop.SpeedCap ) end end end) end function M.stopAntiDrop() M.AntiDrop.Enabled = false if M._antiDropConn then M._antiDropConn:Disconnect() M._antiDropConn = nil end if M._antiDropHealthConn then M._antiDropHealthConn:Disconnect() M._antiDropHealthConn = nil end if M._antiDropDeathConn then M._antiDropDeathConn:Disconnect() M._antiDropDeathConn = nil end if M._antiDropResetBlocked then pcall(function() game:GetService("StarterGui"):SetCore("ResetButtonCallback", nil) end) M._antiDropResetBlocked = false end M._antiDropCharacter = nil M._antiDropHumanoid = nil M._antiDropRoot = nil end function M.toggleAntiDrop() if M.AntiDrop.Enabled then M.stopAntiDrop() else M.startAntiDrop() end end -- ============================================================ -- OPTIMIZED ANTI-DIE SYSTEM (LAG FREE) -- ============================================================ M.AntiDie = { Enabled = false, BillboardVisible = true, } M._antiDieConns = {} M._antiDieHeartbeat = nil M._antiDieBillboard = nil M._antiDieBillboardFrame = nil M._antiDieUpdater = nil M._antiDieHealthConn = nil M._antiDieStateConn = nil M._antiDieCharConn = nil -- Optimized billboard (only updates when needed) local function createAntiDieBillboard(char) if not char then return end local head = char:FindFirstChild("Head") if not head then return end -- Clean up old billboard if M._antiDieBillboard then pcall(function() M._antiDieBillboard:Destroy() end) M._antiDieBillboard = nil end if M._antiDieUpdater then M._antiDieUpdater:Disconnect() M._antiDieUpdater = nil end local camera = Workspace.CurrentCamera M._antiDieBillboard = Instance.new("ScreenGui") M._antiDieBillboard.Name = "AntiDieBillboard" M._antiDieBillboard.ResetOnSpawn = false M._antiDieBillboard.IgnoreGuiInset = true M._antiDieBillboard.ZIndexBehavior = Enum.ZIndexBehavior.Sibling M._antiDieBillboard.Parent = getSafeGuiParent() local frame = Instance.new("Frame", M._antiDieBillboard) frame.Size = UDim2.new(0, 200, 0, 60) frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0) frame.BackgroundTransparency = 0.3 frame.BorderSizePixel = 0 Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 8) frame.Position = UDim2.new(0.5, -100, 0.5, -30) M._antiDieBillboardFrame = frame local txt1 = Instance.new("TextLabel", frame) txt1.Size = UDim2.new(1, 0, 0.5, 0) txt1.Position = UDim2.new(0, 0, 0, 0) txt1.BackgroundTransparency = 1 txt1.Text = "ANTI DIE" txt1.TextColor3 = Color3.fromRGB(255, 215, 0) txt1.Font = Enum.Font.GothamBlack txt1.TextSize = 20 txt1.TextXAlignment = Enum.TextXAlignment.Center txt1.TextYAlignment = Enum.TextYAlignment.Bottom local txt2 = Instance.new("TextLabel", frame) txt2.Size = UDim2.new(1, 0, 0.5, 0) txt2.Position = UDim2.new(0, 0, 0.5, 0) txt2.BackgroundTransparency = 1 txt2.Text = "discord.gg/conquest" txt2.TextColor3 = Color3.fromRGB(255, 215, 0) txt2.Font = Enum.Font.GothamBold txt2.TextSize = 14 txt2.TextXAlignment = Enum.TextXAlignment.Center txt2.TextYAlignment = Enum.TextYAlignment.Top -- OPTIMIZED: Only update billboard position every 4 frames local frameSkip = 0 M._antiDieUpdater = RunService.Heartbeat:Connect(function() if not M._antiDieBillboard or not M._antiDieBillboard.Parent then if M._antiDieUpdater then M._antiDieUpdater:Disconnect() M._antiDieUpdater = nil end return end if not M.AntiDie.BillboardVisible then if frame then frame.Visible = false end return end frameSkip = frameSkip + 1 if frameSkip % 4 ~= 0 then return end -- Update every 4 frames (15fps update) if not head or not head.Parent then if frame then frame.Visible = false end return end local pos, onScreen = camera:WorldToScreenPoint(head.Position + Vector3.new(0, 2, 0)) if onScreen then frame.Position = UDim2.new(0, pos.X - 100, 0, pos.Y - 40) frame.Visible = true else frame.Visible = false end end) end local function destroyAntiDieBillboard() if M._antiDieUpdater then M._antiDieUpdater:Disconnect() M._antiDieUpdater = nil end if M._antiDieBillboard then pcall(function() M._antiDieBillboard:Destroy() end) M._antiDieBillboard = nil end M._antiDieBillboardFrame = nil end -- Optimized: Single character protection with minimal connections local function protectCharacter(char) if not char then return end local hum = char:FindFirstChildOfClass("Humanoid") if not hum then return end hum.MaxHealth = math.huge hum.Health = math.huge -- Clean up old connections if M._antiDieHealthConn then M._antiDieHealthConn:Disconnect() M._antiDieHealthConn = nil end if M._antiDieStateConn then M._antiDieStateConn:Disconnect() M._antiDieStateConn = nil end -- OPTIMIZED: Health changed (only fires when health changes) M._antiDieHealthConn = hum:GetPropertyChangedSignal("Health"):Connect(function() if not M.AntiDie.Enabled then return end if hum.Health < hum.MaxHealth then hum.Health = math.huge end end) -- State changed (only fires on state change) M._antiDieStateConn = hum.StateChanged:Connect(function(_, new) if not M.AntiDie.Enabled then return end if new == Enum.HumanoidStateType.Dead then hum.Health = math.huge hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false) end end) hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false) -- OPTIMIZED: Single heartbeat for health check (runs every other frame) if M._antiDieHeartbeat then M._antiDieHeartbeat:Disconnect() M._antiDieHeartbeat = nil end local frameSkip = 0 M._antiDieHeartbeat = RunService.Heartbeat:Connect(function() if not M.AntiDie.Enabled then return end frameSkip = frameSkip + 1 if frameSkip % 2 ~= 0 then return end -- Check every other frame if hum and hum.Parent and hum.Health < hum.MaxHealth then hum.Health = math.huge end end) createAntiDieBillboard(char) end function M.startAntiDie() if M.AntiDie.Enabled then return end M.AntiDie.Enabled = true -- Clean up old connections for _, c in ipairs(M._antiDieConns) do pcall(function() c:Disconnect() end) end M._antiDieConns = {} if M._antiDieCharConn then M._antiDieCharConn:Disconnect() M._antiDieCharConn = nil end local char = player.Character if char then protectCharacter(char) end M._antiDieCharConn = player.CharacterAdded:Connect(function(c) if not M.AntiDie.Enabled then return end task.wait(0.1) -- Clean up old character connections if M._antiDieHealthConn then M._antiDieHealthConn:Disconnect() M._antiDieHealthConn = nil end if M._antiDieStateConn then M._antiDieStateConn:Disconnect() M._antiDieStateConn = nil end protectCharacter(c) end) table.insert(M._antiDieConns, M._antiDieCharConn) end function M.stopAntiDie() M.AntiDie.Enabled = false -- Clean up all connections if M._antiDieHealthConn then M._antiDieHealthConn:Disconnect() M._antiDieHealthConn = nil end if M._antiDieStateConn then M._antiDieStateConn:Disconnect() M._antiDieStateConn = nil end if M._antiDieCharConn then M._antiDieCharConn:Disconnect() M._antiDieCharConn = nil end if M._antiDieHeartbeat then M._antiDieHeartbeat:Disconnect() M._antiDieHeartbeat = nil end for _, c in ipairs(M._antiDieConns) do pcall(function() c:Disconnect() end) end M._antiDieConns = {} destroyAntiDieBillboard() local char = player.Character if char then local hum = char:FindFirstChildOfClass("Humanoid") if hum then hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true) hum.MaxHealth = 100 hum.Health = 100 end end end function M.toggleAntiDie() if M.AntiDie.Enabled then M.stopAntiDie() else M.startAntiDie() end end -- ============================================================ -- MEDUSA COUNTER FUNCTIONS (OPTIMIZED) -- ============================================================ M.medusaCounterEnabled = false M._medusaCounterConn = nil M._medusaFrameSkip = 0 function M.startMedusaCounter() if M._medusaCounterConn then return end M.medusaCounterEnabled = true M._medusaFrameSkip = 0 M._medusaCounterConn = RunService.Heartbeat:Connect(function() if not M.medusaCounterEnabled then return end M._medusaFrameSkip = M._medusaFrameSkip + 1 if M._medusaFrameSkip % 2 ~= 0 then return end -- Check every other frame local char = player.Character if not char then return end local hum = char:FindFirstChildOfClass("Humanoid") if not hum then return end local state = hum:GetState() if state == Enum.HumanoidStateType.Ragdoll or state == Enum.HumanoidStateType.Physics then hum:ChangeState(Enum.HumanoidStateType.Running) end end) end function M.stopMedusaCounter() M.medusaCounterEnabled = false if M._medusaCounterConn then M._medusaCounterConn:Disconnect() M._medusaCounterConn = nil end end function M.toggleMedusaCounter() if M.medusaCounterEnabled then M.stopMedusaCounter() else M.startMedusaCounter() end return M.medusaCounterEnabled end -- ============================================================ -- BAT COUNTER FUNCTIONS (OPTIMIZED) -- ============================================================ M.batCounterEnabled = false M._batCounterConn = nil M._batFrameSkip = 0 function M.startBatCounter() if M._batCounterConn then return end M.batCounterEnabled = true M._batFrameSkip = 0 M._batCounterConn = RunService.Heartbeat:Connect(function() if not M.batCounterEnabled then return end M._batFrameSkip = M._batFrameSkip + 1 if M._batFrameSkip % 2 ~= 0 then return end local char = player.Character if not char then return end local hum = char:FindFirstChildOfClass("Humanoid") if not hum then return end local state = hum:GetState() if state == Enum.HumanoidStateType.Ragdoll or state == Enum.HumanoidStateType.Physics then hum:ChangeState(Enum.HumanoidStateType.Running) end end) end function M.stopBatCounter() M.batCounterEnabled = false if M._batCounterConn then M._batCounterConn:Disconnect() M._batCounterConn = nil end end function M.toggleBatCounter() if M.batCounterEnabled then M.stopBatCounter() else M.startBatCounter() end return M.batCounterEnabled end -- ============================================================ -- REMOVE ACCESSORIES FUNCTIONS -- ============================================================ M.removeAccEnabled = false M._removeAccConn = nil function M.startRemoveAcc() if M._removeAccConn then return end M.removeAccEnabled = true M._removeAccConn = player.CharacterAdded:Connect(function(char) if not M.removeAccEnabled then return end task.wait(0.5) for _, child in ipairs(char:GetChildren()) do if child:IsA("Accessory") or child:IsA("Hat") or child:IsA("Shirt") or child:IsA("Pants") then pcall(function() child:Destroy() end) end end end) end function M.stopRemoveAcc() M.removeAccEnabled = false if M._removeAccConn then M._removeAccConn:Disconnect() M._removeAccConn = nil end end function M.toggleRemoveAcc() if M.removeAccEnabled then M.stopRemoveAcc() else M.startRemoveAcc() end return M.removeAccEnabled end -- ============================================================ -- PLAYER ESP FUNCTIONS -- ============================================================ M.playerESPEnabled = false M._espList = {} M.showPlayerSpeeds = false function M.toggleESP(on) M.playerESPEnabled = on if not on then for _, esp in ipairs(M._espList) do pcall(function() esp:Destroy() end) end M._espList = {} end end function M.togglePlayerSpeeds(on) M.showPlayerSpeeds = on end -- ============================================================ -- AUTO MOVE SWING FUNCTIONS -- ============================================================ M.autoMoveSwingEnabled = false M.autoMoveSwingInterval = 0.3 M._alSwingDebounce = false M._arSwingDebounce = false function M.toggleAutoMoveSwing() M.autoMoveSwingEnabled = not M.autoMoveSwingEnabled return M.autoMoveSwingEnabled end -- ============================================================ -- DROP BRAINROT FUNCTION -- ============================================================ M.dropActive = false M.DROP_ASCEND_DURATION = 0.2 M.DROP_ASCEND_SPEED = 150 function M.runDrop() if M.dropActive then return end M.dropActive = true local char = player.Character if not char then M.dropActive = false return end local tool = char:FindFirstChildOfClass("Tool") if not tool then M.dropActive = false return end local hum = char:FindFirstChildOfClass("Humanoid") if not hum then M.dropActive = false return end pcall(function() hum:UnequipTools() tool.Parent = workspace tool:SetAttribute("Dropped", true) end) local root = char:FindFirstChild("HumanoidRootPart") if root then local startPos = root.Position local targetPos = startPos + Vector3.new(0, M.DROP_ASCEND_SPEED or 150, 0) local duration = M.DROP_ASCEND_DURATION or 0.2 local startTime = tick() repeat local elapsed = tick() - startTime local progress = math.min(elapsed / duration, 1) local eased = progress * progress * (3 - 2 * progress) local currentY = startPos.Y + (targetPos.Y - startPos.Y) * eased root.CFrame = CFrame.new(root.Position.X, currentY, root.Position.Z) task.wait(0.01) until progress >= 1 end M.dropActive = false end -- ============================================================ -- AUTO CARRY SPEED & AUTO LAGGER CARRY -- ============================================================ M.AutoCarry = { Enabled = false, AutoLaggerCarry = false, CheckInterval = 0.3, } M._autoCarryConn = nil function M.checkCarryState() local char = player.Character if not char then return false end for _, item in ipairs(char:GetChildren()) do if item:IsA("Tool") then local name = item.Name:lower() if name:find("brainrot", 1, true) or name:find("skibidi", 1, true) or name:find("toilet", 1, true) then return true end end end local hum = char:FindFirstChildOfClass("Humanoid") if hum and hum.WalkSpeed < 25 then return true end local ok, val = pcall(function() return player:GetAttribute("Stealing") end) if ok and val == true then return true end return false end function M.startAutoCarry() if M._autoCarryConn then return end M._autoCarryConn = RunService.Heartbeat:Connect(function() if not M.AutoCarry.Enabled then return end local isCarrying = M.checkCarryState() if isCarrying then if M.AutoCarry.AutoLaggerCarry then M.laggerCarryActive = true M.laggerModeEnabled = false M.carrySpeedActive = false else M.carrySpeedActive = true M.laggerCarryActive = false M.laggerModeEnabled = false end else if not M._prevCarryState then if M.laggerCarryActive and M.AutoCarry.AutoLaggerCarry then M.laggerCarryActive = false elseif M.carrySpeedActive and not M.AutoCarry.AutoLaggerCarry then M.carrySpeedActive = false end end end M._prevCarryState = isCarrying end) end function M.stopAutoCarry() if M._autoCarryConn then M._autoCarryConn:Disconnect() M._autoCarryConn = nil end M._prevCarryState = false end function M.toggleAutoCarry() M.AutoCarry.Enabled = not M.AutoCarry.Enabled if M.AutoCarry.Enabled then M.startAutoCarry() else M.stopAutoCarry() end return M.AutoCarry.Enabled end function M.toggleAutoLaggerCarry() M.AutoCarry.AutoLaggerCarry = not M.AutoCarry.AutoLaggerCarry return M.AutoCarry.AutoLaggerCarry end -- ============================================================ -- BALENCI STEAL SYSTEM -- ============================================================ M.Steal = { AutoStealEnabled = false, StealRadius = 61, StealDuration = 1.3, StealDelay = 0.25, StopTime = 0.96, DelayRadius = 9, StopEnabled = true, Data = {} } M.isStealing = false M.stealConn = nil M.progressConn = nil M.animalCache = {} M.promptCache = {} M.stealCache = {} M.stealMode = "V1" M.stealBarSize = 300 M.autoRadiusEnabled = false local function isMyPlot(plotName) local plots = workspace:FindFirstChild("Plots") if not plots then return false end local plot = plots:FindFirstChild(plotName) if not plot then return false end local sign = plot:FindFirstChild("PlotSign") if sign then local yb = sign:FindFirstChild("YourBase") if yb and yb:IsA("BillboardGui") then return yb.Enabled == true end end return false end local function findNearestPrompt() local char = player.Character if not char then return nil, nil end local root = char:FindFirstChild("HumanoidRootPart") if not root then return nil, nil end local plots = workspace:FindFirstChild("Plots") if not plots then return nil, nil end local nearestPrompt, nearestDist, nearestName = nil, math.huge, nil for _, plot in ipairs(plots:GetChildren()) do if isMyPlot(plot.Name) then continue end local pods = plot:FindFirstChild("AnimalPodiums") if not pods then continue end for _, pod in ipairs(pods:GetChildren()) do pcall(function() local base = pod:FindFirstChild("Base") local spawn = base and base:FindFirstChild("Spawn") if spawn then local dist = (spawn.Position - root.Position).Magnitude if dist < nearestDist and dist <= M.Steal.StealRadius then local att = spawn:FindFirstChild("PromptAttachment") if att then for _, child in ipairs(att:GetChildren()) do if child:IsA("ProximityPrompt") and child.ActionText and child.ActionText:find("Steal") then nearestPrompt = child nearestDist = dist nearestName = pod.Name break end end end end end end) end end return nearestPrompt, nearestName end local function executeSteal(prompt, podName) if M.isStealing then return end if not M.Steal.Data[prompt] then M.Steal.Data[prompt] = { hold = {}, trigger = {}, ready = true } pcall(function() if getconnections then for _, c in ipairs(getconnections(prompt.PromptButtonHoldBegan)) do if c.Function then table.insert(M.Steal.Data[prompt].hold, c.Function) end end for _, c in ipairs(getconnections(prompt.Triggered)) do if c.Function then table.insert(M.Steal.Data[prompt].trigger, c.Function) end end end end) end local data = M.Steal.Data[prompt] if not data.ready then return end data.ready = false M.isStealing = true if M.statusFill then M.statusFill.Size = UDim2.new(0, 0, 1, 0) end if M.statusPctLbl then M.statusPctLbl.Text = "0%" end task.spawn(function() for _, f in ipairs(data.hold) do task.spawn(f) end local startTime = tick() local duration = M.Steal.StealDuration local promptFired = false local stopTime = M.Steal.StopTime or 0.96 local delayRadius = M.Steal.DelayRadius or 9 local stopEnabled = M.Steal.StopEnabled ~= false if stopEnabled then while M.isStealing and M.Steal.AutoStealEnabled do local elapsed = tick() - startTime if elapsed >= stopTime then break end if M.statusFill then M.statusFill.Size = UDim2.new(math.clamp(elapsed / duration, 0, 1), 0, 1, 0) end if M.statusPctLbl then M.statusPctLbl.Text = math.floor(math.clamp(elapsed / duration, 0, 1) * 100) .. "%" end if not prompt.Parent or not prompt.Parent.Parent then break end local char = player.Character local hrp = char and char:FindFirstChild("HumanoidRootPart") if hrp and (hrp.Position - prompt.Parent.Parent.Position).Magnitude > M.Steal.StealRadius then break end task.wait() end local stopProgress = math.clamp(stopTime / duration, 0, 1) if M.statusFill then M.statusFill.Size = UDim2.new(stopProgress, 0, 1, 0) end if M.statusPctLbl then M.statusPctLbl.Text = math.floor(stopProgress * 100) .. "%" end local phase2Timeout = math.max(2.99 - stopTime - math.max(duration - stopTime, 0), 0.05) local phase2Start = tick() while M.isStealing and M.Steal.AutoStealEnabled do if tick() - phase2Start >= phase2Timeout then if M.statusFill then M.statusFill.Size = UDim2.new(0, 0, 1, 0) end if M.statusPctLbl then M.statusPctLbl.Text = "0%" end data.ready = true M.isStealing = false task.wait() local newPrompt, newName = findNearestPrompt() if newPrompt then executeSteal(newPrompt, newName) end return end if not prompt.Parent or not prompt.Parent.Parent then M.isStealing = false if M.statusFill then M.statusFill.Size = UDim2.new(0, 0, 1, 0) end if M.statusPctLbl then M.statusPctLbl.Text = "0%" end data.ready = true return end local char = player.Character local hrp = char and char:FindFirstChild("HumanoidRootPart") if hrp then local dist = (hrp.Position - prompt.Parent.Parent.Position).Magnitude if dist <= delayRadius then break elseif dist > M.Steal.StealRadius then M.isStealing = false if M.statusFill then M.statusFill.Size = UDim2.new(0, 0, 1, 0) end if M.statusPctLbl then M.statusPctLbl.Text = "0%" end data.ready = true return end end task.wait() end if M.isStealing and M.Steal.AutoStealEnabled then local fillStart = tick() local fillDuration = math.max(duration - stopTime, 0.05) while true do local fp = math.clamp((tick() - fillStart) / fillDuration, 0, 1) if M.statusFill then M.statusFill.Size = UDim2.new(stopProgress + fp * (1 - stopProgress), 0, 1, 0) end if M.statusPctLbl then M.statusPctLbl.Text = math.floor((stopProgress + fp * (1 - stopProgress)) * 100) .. "%" end if fp >= 1 and not promptFired then promptFired = true pcall(function() for _, f in ipairs(data.trigger) do task.spawn(f) end local remote = ReplicatedStorage:FindFirstChild("StealAnimal") if remote and podName then remote:FireServer(podName) end if prompt then prompt:Fire() end end) break end task.wait() end end else while M.isStealing and M.Steal.AutoStealEnabled do local elapsed = tick() - startTime local progress = math.clamp(elapsed / duration, 0, 1) if M.statusFill then M.statusFill.Size = UDim2.new(progress, 0, 1, 0) end if M.statusPctLbl then M.statusPctLbl.Text = math.floor(progress * 100) .. "%" end if not prompt.Parent or not prompt.Parent.Parent then break end local char = player.Character local hrp = char and char:FindFirstChild("HumanoidRootPart") if hrp and (hrp.Position - prompt.Parent.Parent.Position).Magnitude > M.Steal.StealRadius then break end if elapsed >= duration and not promptFired then promptFired = true pcall(function() for _, f in ipairs(data.trigger) do task.spawn(f) end local remote = ReplicatedStorage:FindFirstChild("StealAnimal") if remote and podName then remote:FireServer(podName) end if prompt then prompt:Fire() end end) break end task.wait() end end if M.statusFill then M.statusFill.Size = UDim2.new(0, 0, 1, 0) end if M.statusPctLbl then M.statusPctLbl.Text = "0%" end data.ready = true M.isStealing = false end) end function M.startAutoSteal() if M.stealConn then return end M.stealConn = RunService.Heartbeat:Connect(function() if not M.Steal.AutoStealEnabled or M.isStealing then return end local p, n = findNearestPrompt() if p then executeSteal(p, n) end end) end function M.stopAutoSteal() if M.stealConn then M.stealConn:Disconnect() M.stealConn = nil end M.isStealing = false if M.statusFill then M.statusFill.Size = UDim2.new(0, 0, 1, 0) end if M.statusPctLbl then M.statusPctLbl.Text = "0%" end end function M.getActiveStealRadius() return M.Steal.StealRadius or 61 end function M.setStealRadius(radius) M.Steal.StealRadius = radius M.updateStatusRadius() end function M.updateStealProgress(progress, label) progress = math.clamp(progress or 0, 0, 1) local pct = math.floor(progress * 100 + 0.5) local col = UI_ACCENT or S3_ACCENT or Color3.fromRGB(255,215,0) if M.statusFill then M.statusFill.Size = UDim2.fromScale(progress, 1) M.statusFill.BackgroundColor3 = col end if M.statusPctLbl then if type(label) == "string" and label ~= "" then M.statusPctLbl.Text = label elseif progress > 0 then M.statusPctLbl.Text = pct .. "%" else local ready = M.Steal and M.Steal.AutoStealEnabled M.statusPctLbl.Text = ready and "READY" or "IDLE" end end if M.statusBarPctLbl then M.statusBarPctLbl.Text = string.format("%d%%", pct) end end function M.updateStatusRadius() if M.statusRadiusLbl then M.statusRadiusLbl.Text = "Radius: " .. tostring(M.getActiveStealRadius()) end end -- ============================================================ -- CONFIG SAVE/LOAD -- ============================================================ local S3_CONFIG_NAME = "ConquestConfig.json" local S3Config = { Theme="GoldRed" } local S3_THEMES = { GoldRed = { Accent=Color3.fromRGB(255,215,0), AccentDim=Color3.fromRGB(200,170,0), Bg=Color3.fromRGB(8,0,0), Row=Color3.fromRGB(16,0,0) }, CrimsonGold = { Accent=Color3.fromRGB(220,20,60), AccentDim=Color3.fromRGB(200,170,0), Bg=Color3.fromRGB(10,0,2), Row=Color3.fromRGB(18,2,6) }, DarkGold = { Accent=Color3.fromRGB(184,134,11), AccentDim=Color3.fromRGB(139,100,8), Bg=Color3.fromRGB(6,0,0), Row=Color3.fromRGB(12,0,0) }, RoyalGold = { Accent=Color3.fromRGB(255,200,0), AccentDim=Color3.fromRGB(200,160,0), Bg=Color3.fromRGB(10,0,0), Row=Color3.fromRGB(20,0,0) }, } if M._savedTheme and S3_THEMES[M._savedTheme] then S3Config.Theme = M._savedTheme end M.colorScheme = S3Config.Theme local function loadS3Config() if type(readfile)~="function" or type(isfile)~="function" then return end local ok,d = pcall(function() if not isfile(S3_CONFIG_NAME) then return nil end return HS:JSONDecode(readfile(S3_CONFIG_NAME)) end) if ok and type(d)=="table" then local the