speedESPEnabled~=nil then M.speedESPEnabled=d.speedESPEnabled end if d.autoResetOnDeath~=nil then M.autoResetOnDeath=d.autoResetOnDeath end if d.bypassAimbotEnabled~=nil then M.bypassAimbotEnabled=d.bypassAimbotEnabled end if d.headlessEnabled~=nil then M.headlessEnabled=d.headlessEnabled end if d.korbloxEnabled~=nil then M.korbloxEnabled=d.korbloxEnabled end if d.animPackEnabled~=nil then M.animPackEnabled=d.animPackEnabled end if type(d.animPack)=="string" then M.animPack=d.animPack end if type(d.uiScale)=="number" then M.uiScale=d.uiScale end if type(d.menuWidth)=="number" then M.menuWidth=math.clamp(math.floor(d.menuWidth+0.5), 360, 1200) end if type(d.menuHeight)=="number" then M.menuHeight=math.clamp(math.floor(d.menuHeight+0.5), 300, 1000) end if type(d.mobileButtonsSize)=="number" then M.mobileButtonsSize=d.mobileButtonsSize end if type(d.fovValue)=="number" then M.fovValue=d.fovValue end if type(d.skyTheme)=="string" then M.currentSkyTheme=d.skyTheme end if d.antiDieEnabled~=nil then M.AntiDie.Enabled=d.antiDieEnabled end if d.antiDropEnabled~=nil then M.AntiDrop.Enabled=d.antiDropEnabled end if d.autoCarryEnabled~=nil then M.AutoCarry.Enabled=d.autoCarryEnabled end if d.autoLaggerCarry~=nil then M.AutoCarry.AutoLaggerCarry=d.autoLaggerCarry end if d.medusaCounterEnabled~=nil then M.medusaCounterEnabled=d.medusaCounterEnabled end if d.batCounterEnabled~=nil then M.batCounterEnabled=d.batCounterEnabled end if d.autoMoveSwingEnabled~=nil then M.autoMoveSwingEnabled=d.autoMoveSwingEnabled end if d.playerESPEnabled~=nil then M.playerESPEnabled=d.playerESPEnabled end if d.showPlayerSpeeds~=nil then M.showPlayerSpeeds=d.showPlayerSpeeds end local function lk(e,d2) if type(d2)~="table" then return end if d2.kb and Enum.KeyCode[d2.kb] then e.kb=Enum.KeyCode[d2.kb] else e.kb=nil end if d2.gp and Enum.KeyCode[d2.gp] then e.gp=Enum.KeyCode[d2.gp] else e.gp=nil end end if d.dropBrainrotKey then lk(M.KB.DropBrainrot,d.dropBrainrotKey) end if d.autoLeftKey then lk(M.KB.A