t char then return end local humanoid = char:FindFirstChildOfClass("Humanoid") if not humanoid then return end if enabled then if humanoid.RigType == Enum.HumanoidRigType.R6 then local rightLeg = char:FindFirstChild("Right Leg") if rightLeg then for _, child in ipairs(rightLeg:GetChildren()) do if child:IsA("SpecialMesh") or child:IsA("CharacterMesh") then child:Destroy() end end rightLeg.Color = DARK_GREY_COLOR rightLeg:GetPropertyChangedSignal("Color"):Connect(function() if rightLeg.Color ~= DARK_GREY_COLOR then rightLeg.Color = DARK_GREY_COLOR end end) local mesh = Instance.new("SpecialMesh") mesh.MeshType = Enum.MeshType.FileMesh mesh.MeshId = KORBLOX_MESH_ID mesh.TextureId = KORBLOX_TEXTURE_ID mesh.Scale = Vector3.new(1, 1, 1) mesh.Name = "KorbloxMesh" mesh.Parent = rightLeg end elseif humanoid.RigType == Enum.HumanoidRigType.R15 then local rightUpperLeg = char:FindFirstChild("RightUpperLeg") if rightUpperLeg then rightUpperLeg.Transparency = 1 local rightLowerLeg = char:FindFirstChild("RightLowerLeg") local rightFoot = char:FindFirstChild("RightFoot") if rightLowerLeg then rightLowerLeg.Transparency = 1 end if rightFoot then rightFoot.Transparency = 1 end local oldKorblox = char:FindFirstChild("KorbloxLeg") if oldKorblox then oldKorblox:Destroy() end local korbloxLeg = Instance.new("Part") korbloxLeg.Name = "KorbloxLeg" korbloxLeg.Size = Vector3.new(1, 2, 1) korbloxLeg.Anchored = false korbloxLeg.CanCollide = false korbloxLeg.Color = DARK_GREY_COLOR korbloxLeg.Parent = char local mesh = Instance.new("SpecialMesh") mesh.MeshType = Enum.MeshType.FileMesh mesh.MeshId = KORBLOX_MESH_ID mesh.TextureId = KORBLOX_TEXTURE_ID mesh.Scale = Vector3.new(1, 1, 1) mesh.Name = "KorbloxMesh" mesh.Parent = korbloxLeg local weld = Instance.new("Weld") weld.Part0 = rightUpperLeg weld.Part1 = korbloxLeg weld.C0 = CFrame.new(0, -0.8, 0) weld.Name = "KorbloxWeld" weld.Parent = korbloxLeg end end else if humanoid.RigType == Enum.HumanoidRigType.R6 then local rightLeg = char:FindFirstChild("Right Leg") if rightLeg then for _, child in ipairs(rightLeg:GetChildren()) do if child:IsA("SpecialMesh") and child.Name == "KorbloxMesh" then child:Destroy() end end rightLeg.Color = Color3.fromRGB(255, 255, 255) end elseif humanoid.RigType == Enum.HumanoidRigType.R15 then local rightUpperLeg = char:FindFirstChild("RightUpperLeg") if rightUpperLeg then rightUpperLeg.Transparency = 0 local rightLowerLeg = char:FindFirstChild("RightLowerLeg") local rightFoot = char:FindFirstChild("RightFoot") if rightLowerLeg then rightLowerLeg.Transparency = 0 end if rightFoot then rightFoot.Transparency = 0 end local korbloxLeg = char:FindFirstChild("KorbloxLeg") if korbloxLeg then korbloxLeg:Destroy() end end end end end function M.applyCharterToChar(char) if not char then return end M.applyHeadlessToChar(char, M.headlessEnabled) M.applyKorbloxToChar(char, M.korbloxEnabled) end -- ============================================================ -- SPEED FUNCTIONS -- ============================================================ function M.getActiveMoveSpeed() if M.hasBrainrotInHand() then return M.LAGGER_CARRY_SPEED end if M.laggerCarryActive then return M.LAGGER_CARRY_SPEED elseif M.laggerModeEnabled then return M.LAGGER_SPEED elseif M.carrySpeedActive then return M.CS else return M.NS end end function M.getAutoPathSpeed() if M.laggerModeEnabled or M.laggerCarryActive then return M.LAGGER_SPEED else return M.NS end end function M.hasBrainrotInHand() local char = player.Character if not char then return false end for _, item in ipairs(char:GetChildren()) do if item:IsA("Tool") then local name = item.Name:lower() if name:find("brainrot", 1, true) or name:find("skibidi", 1, true) or name:find("toilet", 1, true) then return true end end end return false end -- ============================================================ -- OPTIMIZED SPEED LOOP -- ============================================================ function M.stopSpeedLoop() if M._speedLoopConn then pcall(function() M._speedLoopConn:Disconnect() end) M._speedLoopConn = nil end end function M.startSpeedLoop() M.stopSpeedLoop() local frameSkip = 0 M._speedLoopConn = RunService.Heartbeat:Connect(function() frameSkip = frameSkip + 1 if frameSkip % 2 ~= 0 then return end -- Run every other frame local char = player.Character if not char then return end local hum = char:FindFirstChildOfClass("Humanoid") local hrp = char:FindFirstChild("HumanoidRootPart") if not hum or not hrp then return end if hum.Health <= 0 or hum.Sit or hum.PlatformStand then return end if M.autoLeftEnabled or M.autoRightEnabled or M.autoBatEnabled then return end if M.dropActive then return end local targetSpeed = M.getActiveMoveSpeed() if not targetSpeed or targetSpeed <= 0 then return end local effectiveSpeed = targetSpeed if M.laggerModeEnabled or M.laggerCarryActive then local jitter = (M.laggerModeEnabled and 1.2 or 0.6) effectiveSpeed = targetSpeed + (math.random() - 0.5) * jitter end if math.abs((hum.WalkSpeed or 16) - effectiveSpeed) > 0.5 then pcall(function() hum.WalkSpeed = effectiveSpeed end) end end) end -- ============================================================ -- INFINITE JUMP -- ============================================================ M.jumpHeld = false M.infJumpThread = nil M._infJumpBoosting = false M._infJumpLastBoost = 0 M.INF_JUMP_BOOST_FORCE = 25 M.INF_JUMP_BOOST_FRAMES = 2 M.INF_JUMP_BOOST_COOLDOWN = 0.12 local function M_applyInfJumpBoost(root) if not root or M._infJumpBoosting then return end local now = tick() if now - M._infJumpLastBoost < M.INF_JUMP_BOOST_COOLDOWN then return end M._infJumpLastBoost = now M._infJumpBoosting = true local bv = Instance.new("BodyVelocity") bv.MaxForce = Vector3.new(0, math.huge, 0) bv.P = 1250 bv.Velocity = Vector3.new(root.Velocity.X, M.INF_JUMP_BOOST_FORCE, root.Velocity.Z) bv.Parent = root local frameCount = 0 local conn conn = RunService.Heartbeat:Connect(function() if frameCount < M.INF_JUMP_BOOST_FRAMES then frameCount = frameCount + 1 if bv and bv.Parent then bv.Velocity = bv.Velocity + Vector3.new(0, 0.01, 0) end else if bv then pcall(function() bv:Destroy() end) end if conn then conn:Disconnect() end M._infJumpBoosting = false end end) end task.spawn(function() local pg = player:WaitForChild("PlayerGui", 10) if pg then local function hookJumpButton(btn) if btn:IsA("GuiButton") and btn.Name == "JumpButton" and not btn:GetAttribute("InfJumpHooked") then btn:SetAttribute("InfJumpHooked", true) btn.MouseButton1Down:Connect(function() if M.infJumpEnabled then M.jumpHeld = true end end) btn.MouseButton1Up:Connect(function() M.jumpHeld = false end) btn.MouseLeave:Connect(function() M.jumpHeld = false end) end end for _, d in ipairs(pg:GetDescendants()) do hookJumpButton(d) end pg.DescendantAdded:Connect(hookJumpButton) end end) UIS.JumpRequest:Connect(function() if M.infJumpEnabled and M.infJumpMode == "manual" then M.jumpHeld = true task.delay(0.08, function() M.jumpHeld = false end) end end) UIS.InputBegan:Connect(function(inp, gpe) if gpe then return end if M.infJumpEnabled and inp.UserInputType == Enum.UserInputType.Keyboard and inp.KeyCode == Enum.KeyCode.Space then M.jumpHeld = true end end) UIS.InputEnded:Connect(function(inp) if inp.UserInputType == Enum.UserInputType.Keyboard and inp.KeyCode == Enum.KeyCode.Space then M.jumpHeld = false end end) function M.startManualInfJumpLoop() if M.infJumpThread then M.infJumpThread:Disconnect() end M.infJumpThread = RunService.Heartbeat:Connect(function() if not M.infJumpEnabled or M.infJumpMode ~= "manual" then return end if not M.jumpHeld then return end local char = player.Character if not char then return end local hum = char:FindFirstChildOfClass("Humanoid") local root = char:FindFirstChild("HumanoidRootPart") if not hum or not root or hum.Health <= 0 then return end M_applyInfJumpBoost(root) end) end function M.stopManualInfJumpLoop() if M.infJumpThread then M.infJumpThread:Disconnect() M.infJumpThread = nil end M.jumpHeld = false M._infJumpBoosting = false end function M.startHoldInfJump() if M.holdInfJumpConn then M.holdInfJumpConn:Disconnect() end M.holdInfJumpConn = RunService.Heartbeat:Connect(function() if not M.infJumpEnabled or M.infJumpMode ~= "hold" then return end local char = player.Character if not char then return end local root = char:FindFirstChild("HumanoidRootPart") local hum = char:FindFirstChildOfClass("Humanoid") if not root or not hum then return end local isJumpHeld = UIS:IsKeyDown(Enum.KeyCode.Space) or M.jumpHeld or (hum.Jump == true) local vel = root.AssemblyLinearVelocity if isJumpHeld and vel.Y < 35 then root.AssemblyLinearVelocity = Vector3.new(vel.X, 55, vel.Z) end vel = root.AssemblyLinearVelocity if vel.Y < -120 then root.AssemblyLinearVelocity = Vector3.new(vel.X, -120, vel.Z) end end) end function M.stopHoldInfJump() if M.holdInfJumpConn then M.holdInfJumpConn:Disconnect() M.holdInfJumpConn = nil end end -- ============================================================ -- OPTIMIZED AUTO LEFT / RIGHT -- ============================================================ function M.stopAutoLeft() M.autoLeftEnabled = false if M.alConn then M.alConn:Disconnect(); M.alConn = nil end M.alPhase = 1 local char = player.Character if char then local h = char:FindFirstChildOfClass("Humanoid") if h then h:Move(Vector3.zero, false) end end end function M.stopAutoRight() M.autoRightEnabled = false if M.arConn then M.arConn:Disconnect(); M.arConn = nil end M.arPhase = 1 local char = player.Character if char then local h = char:FindFirstChildOfClass("Humanoid") if h then h:Move(Vector3.zero, false) end end end function M.startAutoLeft() if M.alConn then M.alConn:Disconnect() end M.alPhase = 1 M.autoLeftEnabled = true local frameSkip = 0 M.alConn = RunService.Heartbeat:Connect(function() if not M.autoLeftEnabled then return end frameSkip = frameSkip + 1 if frameSkip % 2 ~= 0 then return end local char = player.Character if not char then return end local hrp = char:FindFirstChild("HumanoidRootPart") local hum = char:FindFirstChildOfClass("Humanoid") if not hrp or not hum then return end local spd = (M.getAutoPathSpeed and M.getAutoPathSpeed()) or (M.NS or 60) if M.alPhase == 1 then local tgt = Vector3.new(M.AP_L1.X, hrp.Position.Y, M.AP_L1.Z) if (tgt - hrp.Position).Magnitude < 1 then M.alPhase = 2 local d = M.AP_L2 - hrp.Position local mv = Vector3.new(d.X, 0, d.Z) if mv.Magnitude > 0.01 then mv = mv.Unit end hum:Move(mv, false) hrp.AssemblyLinearVelocity = Vector3.new(mv.X * spd, hrp.AssemblyLinearVelocity.Y, mv.Z * spd) return end local d = M.AP_L1 - hrp.Position local mv = Vector3.new(d.X, 0, d.Z) if mv.Magnitude > 0.01 then mv = mv.Unit end hum:Move(mv, false) hrp.AssemblyLinearVelocity = Vector3.new(mv.X * spd, hrp.AssemblyLinearVelocity.Y, mv.Z * spd) elseif M.alPhase == 2 then local tgt = Vector3.new(M.AP_L2.X, hrp.Position.Y, M.AP_L2.Z) if (tgt - hrp.Position).Magnitude < 1 then hum:Move(Vector3.zero, false) hrp.AssemblyLinearVelocity = Vector3.zero M.autoLeftEnabled = false if M.alConn then M.alConn:Disconnect(); M.alConn = nil end M.alPhase = 1 return end local d = M.AP_L2 - hrp.Position local mv = Vector3.new(d.X, 0, d.Z) if mv.Magnitude > 0.01 then mv = mv.Unit end hum:Move(mv, false) hrp.AssemblyLinearVelocity = Vector3.new(mv.X * spd, hrp.AssemblyLinearVelocity.Y, mv.Z * spd) end if M.autoMoveSwingEnabled and not M._alSwingDebounce then M._alSwingDebounce = true local bat = M.findBatForAimbot() if bat then if bat.Parent ~= char then pcall(function() hum:EquipTool(bat) end) end pcall(function() bat:Activate() end) end task.delay(M.autoMoveSwingInterval or 0.3, function() M._alSwingDebounce = false end) end end) end function M.startAutoRight() if M.arConn then M.arConn:Disconnect() end M.arPhase = 1 M.autoRightEnabled = true local frameSkip = 0 M.arConn = RunService.Heartbeat:Connect(function() if not M.autoRightEnabled then return end frameSkip = frameSkip + 1 if frameSkip % 2 ~= 0 then return end local char = player.Character if not char then return end loc