lth > 0 then hum:ChangeState(Enum.HumanoidStateType.Running) end workspace.CurrentCamera.CameraSubject = hum root.Anchored = false root.AssemblyLinearVelocity = Vector3.zero root.AssemblyAngularVelocity = Vector3.zero end end) end function M.stopAntiRagdoll() if M.Conns.antiRag then M.Conns.antiRag:Disconnect() M.Conns.antiRag = nil end end -- ============================================================ -- AUTO TP -- ============================================================ function M.doAutoTPDown(force) local char=player.Character if not char then return end local hrp=char:FindFirstChild("HumanoidRootPart") if not hrp then return end local hum2=char:FindFirstChildOfClass("Humanoid") if not hum2 then return end if not force then if hum2.FloorMaterial~=Enum.Material.Air then return end if not(hrp.Position.Y>=M.autoTPHeight) then return end end hrp.CFrame=CFrame.new(hrp.Position.X,-7.00,hrp.Position.Z)*CFrame.Angles(0,select(2,hrp.CFrame:ToEulerAnglesYXZ()),0) hrp.Velocity=Vector3.zero end function M.startAutoTP() if M.autoTPConn then task.cancel(M.autoTPConn);M.autoTPConn=nil end M.autoTPConn=task.spawn(function() while M.autoTPEnabled do task.wait(0.1) pcall(function() M.doAutoTPDown(false) end) end end) end function M.stopAutoTP() M.autoTPEnabled=false if M.autoTPConn then task.cancel(M.autoTPConn);M.autoTPConn=nil end end function M.runTPFloor() pcall(function() M.doAutoTPDown(true) end) end -- ============================================================ -- UNWALK -- ============================================================ M.unwalkSavedAnimate = nil function M.startUnwalk() local c=player.Character if not c then return end local hum=c:FindFirstChildOfClass("Humanoid") if hum then for _,t in ipairs(hum:GetPlayingAnimationTracks()) do t:Stop() end end local anim=c:FindFirstChild("Animate") if anim then M.unwalkSavedAnimate=anim:Clone() anim:Destroy() end end function M.stopUnwalk() local c=player.Character if c and M.unwalkSavedAnimate then M.unwalkSavedAnimate:Clone().Parent=c M.unwalkSavedAnimate=nil end end -- ============================================================ -- ANTI-LAG -- ============================================================ function M.enableAntiLag() M.antiLagEnabled = true Lighting.GlobalShadows = false Lighting.FogEnd = 1e10 Lighting.Brightness = 1 Lighting.EnvironmentDiffuseScale = 0 Lighting.EnvironmentSpecularScale = 0 for _, e in pairs(Lighting:GetChildren()) do pcall(function() if e:IsA("BlurEffect") or e:IsA("SunRaysEffect") or e:IsA("ColorCorrectionEffect") or e:IsA("BloomEffect") or e:IsA("DepthOfFieldEffect") then e.Enabled = false end end) end end function M.disableAntiLag() M.antiLagEnabled = false Lighting.GlobalShadows = true Lighting.FogEnd = 100000 Lighting.Brightness = 2 Lighting.EnvironmentDiffuseScale = 1 Lighting.EnvironmentSpecularScale = 1 end -- ============================================================ -- ANTI-SUMMER BASE -- ============================================================ function M.enableAntiSummerBase() M.antiSummerBaseEnabled = true end function M.disableAntiSummerBase() M.antiSummerBaseEnabled = false end -- ============================================================ -- STRETCH REZ -- ============================================================ function M.enableStretchRez() M.stretchRezEnabled=true if M.stretchRezConn then M.stretchRezConn:Disconnect() end pcall(function() RunService:UnbindFromRenderStep("S3_Stretch") end) pcall(function() RunService:BindToRenderStep("S3_Stretch",Enum.RenderPriority.Last.Value-1,function() local cam=workspace.CurrentCamera if cam then cam.CFrame=cam.CFrame*CFrame.new(0,0,0,1,0,0,0,0.8,0,0,0,1) end end) end) end function M.disableStretchRez() M.stretchRezEnabled=false pcall(function() RunService:UnbindFromRenderStep("S3_Stretch") end) end -- ============================================================ -- ANTI-KICK -- ============================================================ function M.enableAntiKick() M.antiKickEnabled = true end function M.disableAntiKick() M.antiKickEnabled = false M.brainrotDetected = false end -- ============================================================ -- SAFE MODE -- ============================================================ function M.enableSafeMode() M.safeModeEnabled = true end function M.disableSafeMode() M.safeModeEnabled = false end -- ============================================================ -- RESET FUNCTIONS -- ============================================================ M._cachedResetRemotes = {} M.cursedResetRemote = nil M._respawning = false local function cacheResetRemotes() local list = {} pcall(function() for _, desc in ipairs(game:GetDescendants()) do if desc:IsA("RemoteEvent") then local n = desc.Name if n:sub(1,3)=="RE/" or n:lower():find("reset") or n:lower():find("balloon") or n:lower():find("respawn") then table.insert(list, desc) if not M.cursedResetRemote and n:sub(1,3)=="RE/" then M.cursedResetRemote = desc end end end end end) M._cachedResetRemotes = list end cacheResetRemotes() player.CharacterAdded:Connect(function() task.defer(cacheResetRemotes) end) function M.cursedInstaReset() if M._respawning then return end M._respawning = true task.delay(2, function() M._respawning = false end) local character = player.Character local humanoid = character and character:FindFirstChildOfClass("Humanoid") task.spawn(function() if M.cursedResetRemote then pcall(function() M.cursedResetRemote:FireServer(M.CURSED_RESET_GUID, player, "balloon") end) pcall(function() M.cursedResetRemote:FireServer(player, "balloon") end) end if M._cachedResetRemotes then for _, r in ipairs(M._cachedResetRemotes) do pcall(function() r:FireServer() end) end end end) if humanoid and humanoid.Health > 0 then pcall(function() humanoid.Health = 0 end) end task.defer(function() task.wait(0.15) pcall(function() player:LoadCharacter() end) end) end -- ============================================================ -- OPTIMIZED MOBILE BUTTONS (MINIMAL CONNECTIONS) -- 