ke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border stroke.Color = Color3.fromRGB(220, 220, 220) stroke.Thickness = 1.2 stroke.Transparency = 0 stroke.Parent = btn local isOn = false btn.BackgroundColor3 = BTN_OFF btn.TextColor3 = TXT_OFF btn.TextStrokeTransparency = 1 stroke.Color = Color3.fromRGB(220, 220, 220) stroke.Thickness = 1.2 stroke.Transparency = 0 local function setOn(v) isOn = v local s = btn:FindFirstChild("BtnStroke") if not s then s = Instance.new("UIStroke") s.Name = "BtnStroke" s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border s.Parent = btn end if v then TweenService:Create(btn, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundColor3 = BTN_ON, TextColor3 = TXT_ON, }):Play() s.Color = Color3.fromRGB(255, 215, 0) s.Thickness = 1.8 s.Transparency = 0 else TweenService:Create(btn, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundColor3 = BTN_OFF, TextColor3 = TXT_OFF, }):Play() s.Color = Color3.fromRGB(220, 220, 220) s.Thickness = 1.2 s.Transparency = 0 end end M.mobBtnRefs[key] = setOn btn.MouseButton1Down:Connect(function() TweenService:Create(btn, TweenInfo.new(0.05), { BackgroundColor3 = BTN_ON, TextColor3 = TXT_ON }):Play() end) btn.MouseButton1Up:Connect(function() if not isOn then TweenService:Create(btn, TweenInfo.new(0.1), { BackgroundColor3 = BTN_OFF, TextColor3 = TXT_OFF }):Play() end end) local dragging = false local dragStart = nil local startPos = nil btn.InputBegan:Connect(function(input) if M.uiLocked then return end if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = true dragStart = input.Position startPos = btn.Position local con con = input.Changed:Connect(function() if input.UserInputState == Enum.UserInputState.End then dragging = false if con then con:Disconnect() end local nx = math.clamp(btn.Position.X.Offset, 0, vp.X - BTN_W) local ny = math.clamp(btn.Position.Y.Offset, 0, vp.Y - BTN_H) btn.Position = UDim2.new(0, nx, 0, ny) M.saveBtnPositions() end end) end end) btn.InputChanged:Connect(function(input) if M.uiLocked then dragging = false; return end if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then local delta = input.Position - dragStart local nx = math.clamp(startPos.X.Offset + delta.X, 0, vp.X - BTN_W) local ny = math.clamp(startPos.Y.Offset + delta.Y, 0, vp.Y - BTN_H) btn.Position = UDim2.new(0, nx, 0, ny) end end) btn.Activated:Connect(function() if key == "drop" then M.runDrop() elseif key == "tpDown" then M.runTPFloor() elseif key == "autoLeft" then if M.autoBatEnabled then M.stopBatAimbot() if M.autoBatSetVisual then M.autoBatSetVisual(false) end if M.mobBtnRefs.autoBat then M.mobBtnRefs.autoBat(false) end end if M.autoRightEnabled then M.autoRightEnabled = false M.stopAutoRight() if M.autoRightSetVisual then M.autoRightSetVisual(false) end if M.mobBtnRefs.autoRight then M.mobBtnRefs.autoRight(false) end end M.autoLeftEnabled = not M.autoLeftEnabled if M.autoLeftEnabled then M.startAutoLeft() else M.stopAutoLeft() end setOn(M.autoLeftEnabled) saveS3Config() elseif key == "autoRight" then if M.autoBatEnabled then M.stopBatAimbot() if M.autoBatSetVisual then M.autoBatSetVisual(false) end if M.mobBtnRefs.autoBat then M.mobBtnRefs.autoBat(false) end end if M.autoLeftEnabled then M.autoLeftEnabled = false M.stopAutoLeft() if M.autoLeftSetVisual then M.autoLeftSetVisual(false) end if M.mobBtnRefs.autoLeft then M.mobBtnRefs.autoLeft(false) end end M.autoRightEnabled = not M.autoRightEnabled if M.autoRightEnabled then M.startAutoRight() else M.stopAutoRight() end setOn(M.autoRightEnabled) saveS3Config() elseif key == "autoBat" then if M.autoLeftEnabled then M.autoLeftEnabled = false M.stopAutoLeft() if M.autoLeftSetVisual then M.autoLeftSetVisual(false) end if M.mobBtnRefs.autoLeft then M.mobBtnRefs.autoLeft(false) end end if M.autoRightEnabled then M.autoRightEnabled = false