dollEnabled = on if on then M.startAntiRagdoll() else M.stopAntiRagdoll() end end) M.setAntiRagVisual = setAntiRag local _, setAntiRagModeUI = uiCardChoiceRow(PCombat, "Anti Ragdoll Mode", "RAGDOLL RESET TYPE", {"Splatter", "No Splatter"}, M.antiRagdollMode == "No Splatter" and 2 or 1, function(newMode) M.antiRagdollMode = (newMode == "No Splatter") and "No Splatter" or "Splatter" if M.antiRagdollEnabled then M.stopAntiRagdoll(); M.startAntiRagdoll() end end ) M.setAntiRagModeUI = setAntiRagModeUI local _, setAutoSwing = uiCardToggleRow(PCombat, "Auto Swing", "CONTINUOUS SWING", M.autoSwingEnabled, function(on) M.autoSwingEnabled = on end) M.setAutoSwingVisual = setAutoSwing local _, setAutoResetOnDeath = uiCardToggleRow(PCombat, "Auto Reset on Death", "FAST RESPAWN", M.autoResetOnDeath, function(on) M.autoResetOnDeath = on end) M.setAutoResetOnDeath = setAutoResetOnDeath -- PAGE: STEAL (BALENCI STYLE) local _, setAutoSteal = uiCardToggleRow(PSteal, "Auto Steal", "AUTOMATIC PET GRAB", M.Steal.AutoStealEnabled, function(on) M.Steal.AutoStealEnabled = on if on then M.startAutoSteal() else M.stopAutoSteal() end end) M.setInstaGrab = setAutoSteal local _, setStealModeChoice = uiCardChoiceRow(PSteal, "Steal Mode", "GRABBER ALGORITHM", {"V1", "V2", "V3"}, (M.stealMode == "V2" or M.stealMode == "Semi") and 2 or (M.stealMode == "V3" and 3 or 1), function(mode) local oldMode = M.stealMode M.stealMode = mode if oldMode ~= M.stealMode and M.Steal.AutoStealEnabled then M.stopAutoSteal(); M.startAutoSteal() end M.updateStatusRadius() end ) M.setStealModeUI = setStealModeChoice local _, srBox = uiCardNumberRow(PSteal, "Grab Radius", "DISTANCE IN STUDS", M.Steal.StealRadius, 0.5, 300, function(v) M.Steal.StealRadius = v; M.setStealRadius(v); M.updateStatusRadius() end) M.radInput = srBox local _, sdBox = uiCardNumberRow(PSteal, "Hold Duration", "HOLD TIME IN SECONDS", M.Steal.StealDuration, 0.1, 10, function(v) M.Steal.StealDuration = v end) M.durationBox = sdBox local _, stopTime