o Right", "AUTO RIGHT DANCE", M.KB.AutoRight) uiKeybindRow(PKeybinds, "Drop Brainrot", "DROP ITEM INSTANT", M.KB.DropBrainrot) uiKeybindRow(PKeybinds, "TP Down", "TELEPORT TO FLOOR", M.KB.TPFloor) uiKeybindRow(PKeybinds, "Anti Die", "TOGGLE ANTI-DIE", M.KB.AntiDie) uiKeybindRow(PKeybinds, "Hide AntiDie", "TOGGLE ANTI-DIE BILLBOARD", M.KB.AntiDieHide) uiKeybindRow(PKeybinds, "Anti Drop", "TOGGLE ANTI-DROP", M.KB.AntiDrop) uiKeybindRow(PKeybinds, "Medusa Counter", "TOGGLE MEDUSA COUNTER", M.KB.MedusaCounter) uiKeybindRow(PKeybinds, "Bat Counter", "TOGGLE BAT COUNTER", M.KB.BatCounter) -- Keybind capture M._keybindCaptureConn = M._keybindCaptureConn pcall(function() if M._keybindCaptureConn then M._keybindCaptureConn:Disconnect() end end) M._keybindCaptureConn = UIS.InputBegan:Connect(function(inp, gpe) if gpe then return end if not activeKBBtn then return end if inp.UserInputType == Enum.UserInputType.Keyboard then local entry = nil for e, b in pairs(M.keybindButtons) do if b == activeKBBtn then entry = e; break end end if entry then if inp.KeyCode == Enum.KeyCode.Escape then resetKeybindCapture() return end entry.kb = (inp.KeyCode ~= Enum.KeyCode.Unknown) and inp.KeyCode or nil entry.gp = nil activeKBBtn.Text = formatKeybindText(entry) activeKBBtn = nil M._anyKeyListening = false if listeningTimeout then task.cancel(listeningTimeout); listeningTimeout = nil end saveS3Config() end end end) -- PAGE: VISUALS local skyNames = M.SkyOrder local skyIdx = 1 for i, s in ipairs(skyNames) do if s == M.currentSkyTheme then skyIdx = i break end end local _, skyChoice = uiCardChoiceRow(PVisuals, "Sky Theme", "ENVIRONMENT SKY", skyNames, skyIdx, function(t) M.currentSkyTheme = t M.CandyApplyCustomSky(t) saveS3Config() end) local fovIdx = 1 for i, f in ipairs(M.fovOptions) do if f == M.fovValue then fovIdx = i break end end local fovOpts = {"80", "120", "180"} local _, fovChoice = uiCardChoiceRow(PVisuals, "FOV", "FIELD OF VIEW", fovOpts, fovIdx, function(v) M.fovValue = tonumber(v)